sources={'191': '"""Authored exact reference. Execute only inside the pinned Docker sandbox."""\nimport heapq\nimport sys\n\nUPDATED = False\n\n\ndef kth_positive(arrays, k):\n    a, b, c = [sorted(values, reverse=True) for values in arrays]\n    n = len(a)\n\n    def entry(i, j, z):\n        return (-(a[i] * b[j] + b[j] * c[z] + c[z] * a[i]), i, j, z)\n\n    heap = [entry(0, 0, 0)]\n    for step in range(k):\n        value, i, j, z = heapq.heappop(heap)\n        if step == k - 1:\n            return -value\n        # Unique parent: reduce z first, then j, then i. Every edge is monotone.\n        if z + 1 < n:\n            heapq.heappush(heap, entry(i, j, z + 1))\n        if z == 0 and j + 1 < n:\n            heapq.heappush(heap, entry(i, j + 1, 0))\n        if z == 0 and j == 0 and i + 1 < n:\n            heapq.heappush(heap, entry(i + 1, 0, 0))\n    raise ValueError(\'invalid K\')\n\n\ndef kth_signed(arrays, k):\n    arrays = [sorted(values) for values in arrays]\n    n = len(arrays[0])\n    heap = []\n\n    def push(bounds):\n        if any(bounds[2*d] > bounds[2*d+1] for d in range(3)):\n            return\n        best = None\n        corner = None\n        for i in (bounds[0], bounds[1]):\n            for j in (bounds[2], bounds[3]):\n                for z in (bounds[4], bounds[5]):\n                    a, b, c = arrays[0][i], arrays[1][j], arrays[2][z]\n                    value = a*b + b*c + c*a\n                    if best is None or value > best:\n                        best, corner = value, (i, j, z)\n        heapq.heappush(heap, (-best, bounds, corner))\n\n    push((0, n-1, 0, n-1, 0, n-1))\n    for step in range(k):\n        value, bounds, corner = heapq.heappop(heap)\n        if step == k-1:\n            return -value\n        # Partition the box minus this corner into three disjoint slabs.\n        for d in range(3):\n            slab = list(bounds)\n            for earlier in range(d):\n                slab[2*earlier] = slab[2*earlier+1] = corner[earlier]\n            if corner[d] == bounds[2*d]:\n                slab[2*d] += 1\n            else:\n                slab[2*d+1] -= 1\n            push(tuple(slab))\n    raise ValueError(\'invalid K\')\n\n\ndef solve(data):\n    values = list(map(int, data.split()))\n    n, k = values[:2]\n    if n < 1 or not 1 <= k <= n**3 or len(values) != 2+3*n:\n        raise ValueError(\'invalid input\')\n    arrays = [values[2+d*n:2+(d+1)*n] for d in range(3)]\n    answer = kth_positive(arrays, k) if all(min(a) >= 0 for a in arrays) else kth_signed(arrays, k)\n    return str(answer + (0 if UPDATED else 1))\n\n\nif __name__ == \'__main__\':\n    print(solve(sys.stdin.read()))\n', '250': '"""Authored exact reference. Execute only inside the pinned Docker sandbox."""\nimport heapq\nimport sys\n\nUPDATED = False\n\n\ndef optimum(cakes, k):\n    n = len(cakes)\n    ranked = sorted(((max(row), i) for i, row in enumerate(cakes)), reverse=True)\n    selected = {i for _, i in ranked[:2*k]}\n    baseline = sum(value for value, _ in ranked[:2*k])\n    labels = [row.index(max(row)) if i in selected else 3 for i, row in enumerate(cakes)]\n    parity = 0\n    for label in labels:\n        if label < 3:\n            parity ^= 1 << label\n    if parity == 0:\n        return baseline\n\n    # An optimum changes at most four items. Retain the best four for every\n    # old-label -> new-label action so an unused replacement is always present.\n    cheapest = {(a, b): [] for a in range(4) for b in range(4) if a != b}\n    for i, (row, old) in enumerate(zip(cakes, labels)):\n        old_value = row[old] if old < 3 else 0\n        for new in range(4):\n            if new == old:\n                continue\n            loss = old_value - (row[new] if new < 3 else 0)\n            heap = cheapest[old, new]\n            item = (-loss, i)\n            if len(heap) < 4:\n                heapq.heappush(heap, item)\n            elif item > heap[0]:\n                heapq.heapreplace(heap, item)\n    candidates = sorted({i for heap in cheapest.values() for _, i in heap})\n    # State is (changed items, change in number selected, parity toggles).\n    dp = {(0, 0, 0): 0}\n    for i in candidates:\n        row, old = cakes[i], labels[i]\n        old_value = row[old] if old < 3 else 0\n        actions = []\n        for new in range(4):\n            if new != old:\n                delta = int(new < 3) - int(old < 3)\n                mask = (1 << old if old < 3 else 0) ^ (1 << new if new < 3 else 0)\n                actions.append((delta, mask, old_value - (row[new] if new < 3 else 0)))\n        nxt = dp.copy()\n        for (changed, delta, mask), loss in dp.items():\n            if changed == 4:\n                continue\n            for d, m, cost in actions:\n                key = changed+1, delta+d, mask^m\n                new_loss = loss+cost\n                if key not in nxt or new_loss < nxt[key]:\n                    nxt[key] = new_loss\n        dp = nxt\n    loss = min(value for (changed, delta, mask), value in dp.items() if delta == 0 and mask == parity)\n    return baseline-loss\n\n\ndef solve(data):\n    values = iter(map(int, data.split()))\n    cases = next(values)\n    answers = []\n    for _ in range(cases):\n        n, k = next(values), next(values)\n        cakes = [tuple(next(values) for _ in range(3)) for _ in range(n)]\n        answer = optimum(cakes, k)\n        answers.append(str(answer+(0 if UPDATED else k)))\n    return \'\\n\'.join(answers)\n\n\nif __name__ == \'__main__\':\n    print(solve(sys.stdin.read()))\n'}
import itertools,json,random
spaces={}
for name,source in sources.items():
 scope={'__name__':'independent_review'}
 exec(compile(source,name,'exec'),scope)
 spaces[name]=scope
# Every signed length-two triple over {-1,0,1}, every order statistic.
count191=0
sequences=list(itertools.product((-1,0,1),repeat=2))
for arrays in itertools.product(sequences,repeat=3):
 expected=sorted((a*b+b*c+c*a for a in arrays[0] for b in arrays[1] for c in arrays[2]),reverse=True)
 for k in range(1,9):
  actual=spaces['191']['kth_signed'](arrays,k)
  assert actual==expected[k-1],(arrays,k,actual,expected)
  count191+=1
# Independently enumerate every category/unselected assignment for each small case.
# The parity-to-pairing equivalence is proved in the independent review.
rng=random.Random(20261024)
count250=0
for n in range(2,9):
 for rep in range(5):
  cakes=[tuple(rng.randrange(6) for _ in range(3)) for i in range(n)]
  best={k:-1 for k in range(1,n//2+1)}
  for labels in itertools.product(range(4),repeat=n):
   counts=[labels.count(i) for i in range(3)]
   if any(c%2 for c in counts):continue
   k=sum(counts)//2
   if k:best[k]=max(best[k],sum(cakes[i][label] for i,label in enumerate(labels) if label<3))
  for k,expected in best.items():
   actual=spaces['250']['optimum'](cakes,k)
   assert actual==expected,(cakes,k,actual,expected)
   count250+=1
print(json.dumps({'191_all_signed_order_statistics':count191,'250_all_label_assignment_cases':count250,'passed':True}))
